const localInput=(s=Date.now()/1000)=>new Date(s*1000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,23);
const labels={monitoring_ended:'会话已结束',assignment_changed:'归属已切换',fresh:'正常上报',interrupted:'上报中断',no_position:'等待首个位置',not_reporting:'未开启上报',uncertain:'位置待核实',pending:'待处理',assigned:'待开始',in_progress:'巡检中',in_transit:'转场中',arrival_pending:'待确认到达',completed:'已完成',cancelled:'已取消',active:'仍在发生',recovered:'观测已恢复',reported:'巡检已上报',investigating:'核查中',closed:'已结案',processing:'处理中',awaiting_confirmation:'等待员工确认',outside:'超出作业区',restricted:'进入受限区',reporting_gap:'上报中断',transfer_timeout:'转场超时',inspection_area:'巡检发现区域问题',inspection_worker:'巡检发现人员问题',browser:'浏览器采集',simulation:'模拟数据',admin:'管理员',leader:'班组负责人',employee:'员工',start:'开始转场',arrive:'申报到达',confirm:'确认',reject:'驳回到达',extend:'延期',cancel:'取消任务',handover:'调组交接',explain:'员工说明',investigate:'核查记录',close:'结案',accept:'接单',progress:'处理进展',resolve:'提交结果',reopen:'反馈未解决',assist:'协助',assign:'指定处理人',proxy_accept:'代组长接单',proxy_progress:'代填进展',proxy_resolve:'代提交处理结果',inspection:'巡检上报'};
const badge=(v)=>`<span class="badge ${['fresh','completed','closed','recovered'].includes(v)?'green':['interrupted','restricted','outside','transfer_timeout','inspection_area','inspection_worker'].includes(v)?'red':'amber'}">${esc(labels[v]||v)}</span>`;
const icon={monitor:'◉',capture:'◎',patrol:'⚑',history:'⌁',transfers:'⇄',events:'△',help:'♡',reports:'▤',admin:'▦',maps:'▧',settings:'⚙',evaluations:'⌖',audit:'≡',notifications:'◇',profile:'○'};
const titles={monitor:'现场总览',capture:'我的上报',patrol:'巡检任务',history:'轨迹回放',transfers:'转场任务',events:'事件核查',help:'求助协同',reports:'统计报表',admin:'基础管理',maps:'地图与区域',settings:'规则与标定',evaluations:'重复性评估',audit:'操作审计',notifications:'消息通知',profile:'个人信息'};
