let S={},page='',generation=0,map=null,mapLayers=null,stream=null,playTimer=null,historyData=[],watch=null,collector=null,lastCapture=null,refreshTimer=null,flushing=false,resetMainScroll=true,scrollQuietUntil=0;
const tabId=sessionStorage.tabId||(sessionStorage.tabId=crypto.randomUUID());
