async function api(path,data,method){const options={method:method||(data===undefined?'GET':'POST'),headers:{}};if(data!==undefined){options.headers['X-CSRF-Token']=S.csrf;if(data instanceof FormData)options.body=data;else{options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}}const response=await fetch('/api'+path,options);let result;try{result=await response.json();}catch{throw Error('服务响应异常');}if(!response.ok)throw Error(result.error||'操作失败');return result;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
const button=(text,action,cls='subtle',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function heading(title,desc,actions=''){return `<div class="page-heading"><div><span class="eyebrow">MINEPATH / ${esc(S.user?.role?.toUpperCase())}</span><h1>${title}</h1><p>${desc}</p></div><div class="button-row">${actions}</div></div>`;}
function table(headers,rows,empty='暂无记录'){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`;}
const panel=(title,content,sub='')=>`<section class="panel"><div class="panel-heading"><h2>${title}</h2><span class="muted small">${sub}</span></div>${content}</section>`;
const field=(name,title,type='text',value='',extra='')=>`<label>${title}<input name="${name}" type="${type}" ${type==='datetime-local'?'step="any"':''} value="${esc(value)}" ${extra}></label>`;
const select=(name,title,items,value='')=>`<label>${title}<select name="${name}">${items.map(i=>`<option value="${esc(i[0])}" ${String(i[0])===String(value)?'selected':''}>${esc(i[1])}</option>`).join('')}</select></label>`;
const reason=title=>`<label>${title||'原因 / 说明'}<textarea name="reason" rows="3" required maxlength="4000"></textarea></label>`;
const teams=()=>S.teams.map(t=>[t.id,t.name]);const areas=()=>S.areas.filter(a=>a.kind==='work').map(a=>[a.id,a.name]);const people=()=>S.employees.filter(p=>!p.historical_only).map(p=>[p.id,p.name+' · '+p.username]);
const name=id=>S.employees.find(p=>p.id===id)?.name||id;
function dialog(title,html,submit){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();const form=$('#modal-body form');if(form)form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');if(b)b.disabled=true;try{const saved=await submit(Object.fromEntries(new FormData(form)),form);$('#modal').close();toast(saved?.message||'已保存');try{await boot(false);await render();}catch(refreshError){if(saved?.local){toast(saved.message);await render();}else throw refreshError;}}catch(err){toast(err.message);}finally{if(b)b.disabled=false;}};}
function formModal(title,html,submit,label='保存'){dialog(title,`<form class="form-grid">${html}<div class="form-actions"><button class="primary" type="submit">${label}</button></div></form>`,submit);}
function timeline(actions){return `<div class="timeline">${actions.map(a=>`<div class="timeline-item"><b>${esc(labels[a.action]||a.action)}</b><span class="muted small"> ${dt(a.at)} · ${esc(a.actor_id)}</span><p>${esc(a.text||a.data||'')}</p></div>`).join('')||'<p class="muted">暂无后续处理记录</p>'}</div>`;}
async function boot(draw=true){S=await api('/bootstrap');$('#login-view').hidden=!!S.user;$('#app-view').hidden=!S.user;if(!S.user){stream?.close();return;}$('#profile-button').textContent=S.user.name+' · '+labels[S.user.role];$('#server-clock').textContent='服务器 '+dt(S.server_time);collector=JSON.parse(sessionStorage.getItem('collector-'+S.user.id)||'null');const menu=S.user.role==='employee'?['capture','patrol','history','transfers','events','help','reports']:['monitor','patrol','history','transfers','events','help','reports'];if(S.user.role==='admin')menu.push('admin','maps','settings','evaluations','audit');$('#nav').innerHTML=menu.map(p=>`<a class="nav-item" href="#${p}" data-page="${p}"><span>${icon[p]}</span>${titles[p]}</a>`).join('');if(!stream){stream=new EventSource('/api/stream');stream.onopen=()=>$('#connection').textContent='实时连接';stream.onerror=()=>$('#connection').textContent='连接重试中';stream.addEventListener('refresh',scheduleLiveRefresh);}if(draw)await render();}
function route(){return location.hash.slice(1)|| (S.user?.role==='employee'?'capture':'monitor');}
function scheduleLiveRefresh(){clearTimeout(refreshTimer);const wait=Math.max(400,scrollQuietUntil-Date.now());refreshTimer=setTimeout(async()=>{if(Date.now()<scrollQuietUntil){scheduleLiveRefresh();return;}try{const n=await api('/monitor');$('#unread-count').textContent=n.unread;if(page==='monitor')updateMonitor(n);else if(['events','transfers','help','notifications','patrol'].includes(page)&&!$('#modal').open)await render({quiet:true});}catch{}},wait);}
async function render(options={}){if(!S.user)return;const n=++generation;const previousPage=page;page=route();const switched=page!==previousPage;resetMainScroll=switched;$('#main').onclick=null;if(switched||!options.quiet){clearInterval(playTimer);playTimer=null;if(map){map.remove();map=null;}}$$('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));if(switched)$('.sidebar').classList.remove('open');if(switched||!$('#main').innerHTML.trim())$('#main').innerHTML='<div class="empty">正在读取记录…</div>';try{const fn=views[page]||views.profile;await fn(n);}catch(e){if(n===generation)$('#main').innerHTML=heading(titles[page]||'工作台','')+panel('无法读取',`<p class="error">${esc(e.message)}</p>${button('重试','refresh')}`);}}
const mainNode=$('#main');
const mainHtml=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');
Object.defineProperty(mainNode,'innerHTML',{configurable:true,get(){return mainHtml.get.call(mainNode);},set(value){const y=window.scrollY;const reset=resetMainScroll;if(!reset&&mainHtml.get.call(mainNode)===value)return;mainHtml.set.call(mainNode,value);const apply=()=>{if(reset){if(window.scrollY)window.scrollTo(0,0);}else if(Math.abs(window.scrollY-y)>1)window.scrollTo(0,y);};apply();requestAnimationFrame(apply);}});
window.addEventListener('scroll',()=>{scrollQuietUntil=Date.now()+700;},{passive:true});
function setMapBackground(at,fit=false){
  if(!map||map.options.crs!==L.CRS.Simple)return;
  const config=MinePathMaps.selectMap(S.site_maps,at),id=config?.id||'builtin';
  if(mapBackgroundId!==id||!mapBackground){
    if(mapBackground)map.removeLayer(mapBackground);
    let image,bounds;
    if(config){image=config.image_url;bounds=MinePathMaps.bounds(config);}
    else{
      const svg='<svg xmlns="http://www.w3.org/2000/svg" width="600" height="240"><rect width="600" height="240" fill="#eef0e9"/><path d="M0 135H600" stroke="#d5d9ce" stroke-width="26"/><path d="M0 135H600" stroke="#fff" stroke-width="1" stroke-dasharray="8 8"/><g fill="#dce1d4"><rect x="25" y="20" width="65" height="22"/><rect x="225" y="20" width="65" height="22"/><rect x="425" y="20" width="65" height="22"/></g></svg>';
      image='data:image/svg+xml,'+encodeURIComponent(svg);bounds=[[-60,-40],[180,560]];
    }
    mapBackground=L.imageOverlay(image,bounds,{opacity:Number($('#map-opacity')?.value||1)}).addTo(map);
    mapBackground.on('error',()=>toast('底图加载失败，请刷新或重新登录后查看'));
    mapBackgroundId=id;
  }
  if(fit)map.fitBounds(mapBackground.getBounds(),{padding:[16,16],animate:false});
  const label=$('#site-map-label');if(label)label.textContent=config?config.name+' · '+dt(config.valid_from):'内置场区示意图';
}
function createMap(target='map',geographic=false){
  if(map){map.remove();map=null;}
  mapBackground=null;mapBackgroundId=null;
  if(!window.L){$('#'+target).innerHTML='<p>地图组件未加载</p>';return;}
  map=L.map(target,{crs:geographic?L.CRS.EPSG3857:L.CRS.Simple,zoomControl:true,minZoom:geographic?0:-12,zoomSnap:.25,zoomDelta:.5,attributionControl:true});
  map.attributionControl.setPrefix('MinePath · '+(geographic?'经纬度空白底图':'场区米制平面'));
  mapLayers=L.layerGroup().addTo(map);
  if(!geographic)setMapBackground(undefined,true);else map.setView([31.2,121.4],15);
  return map;
}
function drawAreas(at=Date.now()/1000){if(!map)return;const source=S.area_history||S.areas;source.filter(a=>a.valid_from<=at&&(!a.valid_to||at<a.valid_to)).forEach(a=>{const pts=JSON.parse(a.polygon).map(p=>[p[1],p[0]]);L.polygon(pts,{color:a.kind==='restricted'?'#bc6551':'#6d8d5b',weight:1.5,fillOpacity:a.kind==='restricted'?.18:.08,dashArray:a.kind==='restricted'?'5 4':undefined}).addTo(mapLayers).bindTooltip(map.getSize().x<600?esc(a.name.length>8?a.name.slice(0,8)+'…':a.name):esc(a.name)+' · '+esc(a.version_id),{permanent:a.kind!=='restricted'||map.getSize().x>=600,direction:'center',className:'area-label'});});}
function pointMarker(p,label,state='fresh',geo=false){const xy=geo?[p.lat,p.lng]:[p.y,p.x];if(xy.some(v=>v===null||v===undefined))return;const color=state==='fresh'?'#245e49':state==='uncertain'?'#bd8b40':'#87918a';L.circleMarker(xy,{radius:6,color:'#fff',weight:2,fillColor:color,fillOpacity:1}).addTo(mapLayers).bindTooltip(`${esc(label)}<br>${dt(p.observed_at)}<br>±${Number(p.accuracy).toFixed(1)}m · ${esc(labels[p.source])}`);if(p.accuracy<10000)L.circle(xy,{radius:geo?p.accuracy:p.accuracy,color,weight:1,fillOpacity:.03,interactive:false}).addTo(mapLayers);}
