'force-end':el=>formModal('管理员强制结束上报',reason('填写结束原因'),f=>api(`/sessions/${el.dataset.id}/end`,f),'确认结束'),
simulation:async()=>{const d=await api('/admin/simulation',{running:!S.simulation_running});S.simulation_running=d.running;toast(d.running?`已启动 ${d.collectors} 个模拟采集器（独立标记来源）`:'已停止模拟流');await boot(false);await render();},
'import-history':async()=>{const d=await api('/admin/import-simulation',{count:100000});toast(`新增 ${d.imported} 条历史模拟记录`);},
'history-geo':()=>{historyGeo=!historyGeo;if(map)map.remove();createMap('map',historyGeo);if(historyData.length){drawTrack(Number($('#seek').value));if(historyGeo){const coords=historyData.filter(p=>p.lat!=null).map(p=>[p.lat,p.lng]);if(coords.length)map.fitBounds(coords,{maxZoom:18,padding:[30,30]});}}else if(!historyGeo)drawAreas();},'load-more':()=>loadHistory(true),play:()=>{if(!historyData.length)return toast('请先查询轨迹');if(playTimer){clearInterval(playTimer);playTimer=null;$('[data-action=play]').textContent='播放';return;}if(Number($('#seek').value)>=Number($('#seek').max))$('#seek').value=$('#seek').min;$('[data-action=play]').textContent='暂停';playTimer=setInterval(()=>{const at=Math.min(Number($('#seek').max),Number($('#seek').value)+Number($('#play-speed').value)/5);$('#seek').value=at;drawTrack(at);if(at>=Number($('#seek').max)){clearInterval(playTimer);playTimer=null;$('[data-action=play]').textContent='播放';}},200);},
'capture-stop':async()=>{if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;}const sid=collector?.session_id||S.work_session?.id;if(!sid)return toast('没有活动会话');await queuePut({id:crypto.randomUUID(),owner:S.user.id,kind:'end',sid,requested_at:Date.now()/1000});await flushQueue();await boot(false);await render();},flush:()=>flushQueue(),
'transfer-new':()=>formModal('下达转场任务',select('user_id','员工',people())+select('from_area','起点',areas())+select('to_area','终点',areas(),'B')+field('allowed_minutes','允许转场时长（分钟）','number',20,'min="1" max="1440" required'),f=>api('/transfers',f),'下达任务'),
allocate:()=>formModal('分配作业区',select('user_id','员工',people())+select('area_id','允许选择的作业区',areas()),f=>api('/allocations',f)),
'transfer-detail':el=>transferDetail(el.dataset.id),'event-detail':el=>eventDetail(el.dataset.id),'help-detail':el=>helpDetail(el.dataset.id),
