'patrol-start':el=>formModal('开始巡检','<div class="notice">开始后显示该作业区的系统提示、正在作业的人员，以及本组未结求助。</div>',()=>api('/inspections/'+el.dataset.id+'/start',{}),'开始巡检'),
'patrol-area-problem':el=>formModal('上报区域问题',select('category','问题类别',[['现场环境','现场环境'],['设备设施','设备设施'],['通道或标识','通道或标识'],['其他','其他']])+`<label>具体情况<textarea name="description" required rows="4" maxlength="4000"></textarea></label>`,f=>api('/inspections/'+el.dataset.id+'/finding',{target:'area',problem:true,category:f.category,description:f.description}),'上报'),
'patrol-area-clear':el=>formModal('记录区域无异常',`<label>检查说明<textarea name="description" required rows="3" maxlength="4000">现场未见需要上报的区域问题。</textarea></label>`,f=>api('/inspections/'+el.dataset.id+'/finding',{target:'area',problem:false,category:'无异常',description:f.description}),'保存'),
'patrol-worker-problem':el=>formModal('上报在岗人员问题',select('category','问题类别',[['人员状态异常','人员状态异常'],['未在指定区域','未在指定区域'],['需要协助','需要协助'],['其他','其他']])+`<label>具体情况<textarea name="description" required rows="4" maxlength="4000"></textarea></label>`,f=>api('/inspections/'+el.dataset.id+'/finding',{target:'worker',problem:true,subject_user_id:el.dataset.user,category:f.category,description:f.description}),'上报'),
'patrol-worker-clear':el=>formModal('记录人员无异常',`<label>检查说明<textarea name="description" required rows="3" maxlength="4000">在岗，未发现需要上报的问题。</textarea></label>`,f=>api('/inspections/'+el.dataset.id+'/finding',{target:'worker',problem:false,subject_user_id:el.dataset.user,category:'无异常',description:f.description}),'保存'),
'patrol-complete':el=>formModal('完成巡检','<div class="notice">完成后不能再代接新的求助。已经接手的求助，仍可在求助协同里继续提交结果。</div>',()=>api('/inspections/'+el.dataset.id+'/complete',{}),'完成巡检'),
'patrol-cancel':el=>formModal('撤回巡检',reason('撤回原因'),f=>api('/inspections/'+el.dataset.id+'/cancel',{reason:f.reason}),'撤回'),
'patrol-help':()=>{location.hash='help';},
'patrol-proxy':el=>{const h=window.inspectionDetail.helps.find(item=>item.id===el.dataset.id);const update=h.proxy_id===S.user.id;formModal(update?'代提交处理结果':'代组长接单',`<p><b>${esc(h.employee_name)}</b> · ${esc(h.category)}</p><p>${esc(h.description)}</p>`+(update?select('action','处理操作',[['proxy_progress','代填进展'],['proxy_resolve','代提交处理结果']]):'<input type="hidden" name="action" value="proxy_accept">')+`<label>说明 / 结果<textarea name="text" required rows="3"></textarea></label><div class="notice">这是代替本组负责人处理。提交结果后，由求助员工确认是否解决。</div>`,f=>api('/help/'+h.id+'/action',{action:f.action,text:f.text}),update?'保存处理':'代接单');},
