'task-confirm':el=>{const t=window.transferItems.find(x=>x.id===el.dataset.id);formModal('确认到达 · 切换作业区',field('effective_at','核实后的实际到达时间','datetime-local',localInput(t.claimed_arrival_at),'required')+reason('核实依据'),f=>api(`/transfers/${el.dataset.id}/confirm`,{...f,effective_at:stamp(f.effective_at)}),'确认生效');},
