'task-cancel':el=>formModal('取消任务并说明后续安排',reason('取消原因')+select('next_instruction','下一步安排',[['原地等待负责人安排','原地等待'],['返回A区；另行下达新任务','返回原区域（须另发新任务）'],['前往其他区域；另行下达新任务','转去其他区域（须另发新任务）']]),f=>api(`/transfers/${el.dataset.id}/cancel`,f)),
'help-new':()=>formModal('发起求助',select('category','类别',[['设备异常','设备异常'],['身体不适','身体不适'],['现场风险','现场风险'],['其他','其他']])+`<label>具体情况<textarea name="description" required rows="4" maxlength="4000"></textarea></label><label>现场照片（选填，最多5MB）<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="notice">没有有效位置也可以提交。离线时先保存在本机，显示待上传。</div>`,async(f,form)=>{const file=form.querySelector('[name=photo]').files[0];if(file&&file.size>5*1024*1024)throw Error('照片不能超过5MB');await queuePut({id:crypto.randomUUID(),owner:S.user.id,kind:'help',category:f.category,description:f.description,photo:file||null});await flushQueue();const pending=(await queueAll()).some(x=>x.id&&x.owner===S.user.id&&x.kind==='help');return {local:true,message:pending?'求助已保存在本机，待上传':'求助已提交'};},'提交求助'),
