$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-error').textContent='';try{const r=await api('/login',Object.fromEntries(new FormData(e.target)));S.csrf=r.csrf;location.hash='';await boot();await flushQueue();}catch(err){$('#login-error').textContent=err.message;}};
$('#logout-button').onclick=async()=>{if(watch!==null){toast('请先结束本机位置采集再退出');return;}await api('/logout',{});stream?.close();stream=null;S.user=null;await boot();};
window.addEventListener('hashchange',render);window.addEventListener('online',()=>{toast('网络已恢复，正在重试本机缓存');flushQueue();});window.addEventListener('offline',()=>{if($('#connection'))$('#connection').textContent='离线 · 本机缓存';});
// IndexedDB保存实际观测和求助；不在离线期间生成或推算位置。
const queueDB=new Promise((resolve,reject)=>{const req=indexedDB.open('minepath-local-queue',1);req.onupgradeneeded=()=>req.result.createObjectStore('queue',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
async function queueOp(mode,fn){const db=await queueDB;return new Promise((resolve,reject)=>{const tx=db.transaction('queue',mode),store=tx.objectStore('queue');const req=fn(store);let out;req.onsuccess=()=>out=req.result;tx.oncomplete=()=>resolve(out);tx.onerror=()=>reject(tx.error);});}
const queuePut=x=>queueOp('readwrite',s=>s.put({...x,created:Date.now()})), queueDelete=id=>queueOp('readwrite',s=>s.delete(id)),queueAll=()=>queueOp('readonly',s=>s.getAll());
async function queueStatus(){if(!S.user)return;const rows=(await queueAll()).filter(x=>x.owner===S.user.id);if($('#queue-status'))$('#queue-status').textContent=`本机待上传：${rows.filter(x=>!x.failed).length} 条；被拒绝保留：${rows.filter(x=>x.failed).length} 条。${rows.filter(x=>x.kind==='end'&&!x.failed).length?'结束请求待服务器确认。':''}${rows.find(x=>x.failed)?.failed?' 最近拒绝原因：'+rows.find(x=>x.failed).failed:''}`;}
async function flushQueue(){if(flushing||!S.user||!navigator.onLine)return;flushing=true;try{const rows=(await queueAll()).filter(x=>x.owner===S.user.id&&!x.failed);const tokens=[...new Set(rows.filter(x=>x.kind==='point').map(x=>x.token))];for(const token of tokens){const points=rows.filter(x=>x.kind==='point'&&x.token===token);for(let i=0;i<points.length;i+=500){const batch=points.slice(i,i+500);let r;try{r=await api('/positions',{collector_token:token,points:batch.map(x=>x.point)});}catch(err){if(err.message.includes('采集授权无效')){for(const p of batch)await queuePut({...p,failed:err.message});continue;}throw err;}for(const result of r.results){const p=batch.find(x=>x.id===result.point_id);if(!p)continue;if(result.status==='rejected')await queuePut({...p,failed:result.reason});else await queueDelete(p.id);}}}for(const row of rows.filter(x=>x.kind==='help')){const data=new FormData();data.set('client_id',row.id);data.set('category',row.category);data.set('description',row.description);if(row.photo)data.set('photo',row.photo,row.photo.name||'photo.jpg');await api('/help',data);await queueDelete(row.id);toast('求助已上传');}for(const row of rows.filter(x=>x.kind==='end')){await api(`/sessions/${row.sid}/end`,{reason:'本人结束上报',client_requested_at:row.requested_at});await queueDelete(row.id);sessionStorage.removeItem('collector-'+S.user.id);collector=null;}}catch(err){if(navigator.onLine)toast(err.message.includes('fetch')?'服务暂不可达，缓存仍在本机，稍后重试':'缓存等待重试：'+err.message);}finally{flushing=false;await queueStatus();}}
setInterval(()=>{if(watch!==null&&S.user&&navigator.onLine)api('/heartbeat',{}).catch(()=>{});flushQueue();},10000);
boot().catch(e=>{$('#login-error').textContent=e.message;});
